    start: { x: 0, z: -52 },
    steps: [
      { text: 'Reach the Solmar National Bank', target: { x: 26, z: 26 }, kind: 'goto', night: true },
      { text: 'Grab the cash inside (press E at the door)', target: { x: 26, z: 26 }, kind: 'grab' },
